 					)
 				})

+				// Test framework BC configs use gmCapable=0, but real deployments default to
+				// gmCapable=1. Without it, ptp4l won't report clock class degradation on sync loss.
+				ptpConfigName := fullConfig.DiscoveredClockUnderTestPtpConfig.Name
+				originalConf := ptptesthelper.EnableGMCapableInPlace(ptpConfigName)
+				DeferCleanup(func() {
+					ptptesthelper.RestorePtp4lConf(ptpConfigName, originalConf)
+				})
+				configFile, err := ptptesthelper.DiscoverPtp4lConfigByProfile(ptpConfigName, slavePodNodeName)
+				Expect(err).NotTo(HaveOccurred())
+				ptptesthelper.WaitForConfigContent(fullConfig, configFile, "gmCapable 1")
+
 				By("Checking initial clock class is Locked (6)")
 				checkClockClassState(fullConfig, strconv.Itoa(int(fbprotocol.ClockClass6)), pkg.TimeoutIn5Minutes)

@@ -3514,6 +3525,20 @@ func waitForClockClass(fullConfig testconfig.TestConfig, expectedState string) {
 }

 func checkClockClassStateReturnBool(fullConfig testconfig.TestConfig, expectedState string) bool {
+	if !ptphelper.IsPTPOperatorVersionAtLeast("4.18") {
+		expected, err := strconv.Atoi(expectedState)
+		if err != nil {
+			return false
+		}
